//! bitBybit desktop app. Unelevated: reads and changes go through the bitBybit service (broker pipe); the app
//! itself never touches system state.
#![cfg_attr(not(test), windows_subsystem = "windows")]

/// Code generated by slint-build from ui/app.slint (not ours to lint).
#[allow(clippy::all, clippy::unwrap_used, clippy::expect_used, clippy::todo, clippy::pedantic)]
mod ui {
    slint::include_modules!();
}

use ui::{AppWindow, AudioRow, ChangeRow, DeviceRow, InterfaceRow, Tr};

mod view;

use bitbybit_audio::profile::AudioEndpoint;
use bitbybit_core::{LocalizedText, text, version};
use bitbybit_domain::snapshot::DeviceSummary;
use bitbybit_localization::TextCatalog;
use bitbybit_network::overview::NetworkOverview;
use slint::{ComponentHandle, ModelRc, VecModel};
use std::rc::Rc;

fn main() -> Result<(), slint::PlatformError> {
    let catalog = TextCatalog::default_catalog();
    let ui = AppWindow::new()?;
    ui.global::<Tr>().on_t(move |key| catalog.get(&key, &[]).into());
    ui.set_version(version().into());
    ui.set_about_version(
        catalog
            .resolve(&text!("app.about.version", "Version {0} · Rust rewrite (preview)", version().to_owned()))
            .into(),
    );
    let weak = ui.as_weak();
    ui.on_refresh(move || load(weak.clone()));
    let weak = ui.as_weak();
    ui.on_make_default(move |id| make_default(weak.clone(), id.to_string()));
    let weak = ui.as_weak();
    ui.on_revert(move |id| revert(weak.clone(), id.to_string()));
    load(ui.as_weak());
    ui.run()
}

/// Asks the broker off the UI thread and applies the result on it.
fn load(weak: slint::Weak<AppWindow>) {
    let catalog = TextCatalog::default_catalog();
    if let Some(ui) = weak.upgrade() {
        ui.set_broker_state(0);
        ui.set_broker_message(
            catalog.resolve(&text!("app.broker.connecting", "Connecting to the bitBybit service…")).into(),
        );
    }
    std::thread::spawn(move || {
        let result = broker::load();
        let audio = audio::endpoints();
        let changes = bitbybit_audio::report::ReportedChange::load(&bitbybit_core::paths::AppPaths::from_environment());
        let _ = slint::invoke_from_event_loop(move || {
            let Some(ui) = weak.upgrade() else { return };
            apply_audio(&ui, audio, catalog);
            apply_changes(&ui, &changes, catalog);
            match result {
                Ok(data) => apply(&ui, &data, catalog),
                Err(problem) => {
                    ui.set_broker_state(2);
                    ui.set_broker_message(catalog.resolve(&problem).into());
                }
            }
        });
    });
}

fn apply_audio(ui: &AppWindow, audio: Result<Vec<AudioEndpoint>, LocalizedText>, catalog: &TextCatalog) {
    match audio {
        Ok(endpoints) => {
            let (rows, subtitle) = view::audio_rows(&endpoints, catalog);
            let rows: Vec<AudioRow> = rows
                .into_iter()
                .map(|r| AudioRow {
                    id: r.id.into(),
                    name: r.name.into(),
                    flow: r.flow.into(),
                    state: r.state.into(),
                    defaults: r.defaults.into(),
                    can_make_default: r.can_make_default,
                })
                .collect();
            ui.set_audio(ModelRc::from(Rc::new(VecModel::from(rows))));
            ui.set_audio_subtitle(subtitle.into());
        }
        Err(problem) => ui.set_audio_subtitle(catalog.resolve(&problem).into()),
    }
}

fn apply_changes(ui: &AppWindow, changes: &[bitbybit_audio::report::ReportedChange], catalog: &TextCatalog) {
    let rows: Vec<ChangeRow> = view::change_rows(changes, catalog)
        .into_iter()
        .map(|c| ChangeRow {
            id: c.id.into(),
            when: c.when.into(),
            kind: c.kind.into(),
            description: c.description.into(),
            status: c.status.into(),
            scope: c.scope.into(),
            can_revert: c.can_revert,
        })
        .collect();
    ui.set_changes(ModelRc::from(Rc::new(VecModel::from(rows))));
}

/// Reverts one user-scope change through the drift-aware coordinator, then reloads everything.
fn revert(weak: slint::Weak<AppWindow>, id: String) {
    std::thread::spawn(move || {
        let catalog = TextCatalog::default_catalog();
        let message =
            audio::revert(&id).map_or_else(|p| catalog.resolve(&p), |status| view::status_text(status, catalog));
        let reload = weak.clone();
        let _ = slint::invoke_from_event_loop(move || {
            if let Some(ui) = weak.upgrade() {
                ui.set_changes_message(message.into());
            }
        });
        load(reload);
    });
}

/// Journals, applies and verifies the change in the user's session, then reloads the list.
fn make_default(weak: slint::Weak<AppWindow>, id: String) {
    std::thread::spawn(move || {
        let catalog = TextCatalog::default_catalog();
        let message = match audio::make_default(&id) {
            Ok(()) => text!(
                "app.audio.defaultSetVerified",
                "Default device changed, verified and recorded in the change journal."
            ),
            Err(problem) => problem,
        };
        let endpoints = audio::endpoints();
        let _ = slint::invoke_from_event_loop(move || {
            let Some(ui) = weak.upgrade() else { return };
            ui.set_audio_message(catalog.resolve(&message).into());
            apply_audio(&ui, endpoints, catalog);
        });
    });
}

/// What one refresh reads from the broker.
struct Loaded {
    broker_version: String,
    network: NetworkOverview,
    devices: Vec<DeviceSummary>,
}

fn apply(ui: &AppWindow, data: &Loaded, catalog: &TextCatalog) {
    let overview = &data.network;
    ui.set_broker_state(1);
    ui.set_broker_message(
        catalog
            .resolve(&text!(
                "app.broker.connected",
                "Connected to the bitBybit service {0}",
                data.broker_version.clone()
            ))
            .into(),
    );
    let (devices, summary) = view::device_rows(&data.devices, catalog);
    let devices: Vec<DeviceRow> = devices
        .into_iter()
        .map(|d| DeviceRow {
            name: d.name.into(),
            class: d.class.into(),
            status: d.status.into(),
            driver: d.driver.into(),
            problem: d.problem,
        })
        .collect();
    ui.set_devices(ModelRc::from(Rc::new(VecModel::from(devices))));
    ui.set_devices_summary(summary.into());
    let (rows, hidden) = view::interface_rows(overview, catalog);
    let rows: Vec<InterfaceRow> = rows
        .into_iter()
        .map(|r| InterfaceRow {
            name: r.name.into(),
            kind: r.kind.into(),
            status: r.status.into(),
            addresses: r.addresses.into(),
            vpn: r.vpn,
            up: r.up,
        })
        .collect();
    ui.set_interfaces(ModelRc::from(Rc::new(VecModel::from(rows))));
    ui.set_route_summary(view::route_summary(overview, catalog).into());
    ui.set_hidden_summary(view::hidden_text(hidden, catalog).into());
}

#[cfg(windows)]
mod broker {
    use super::*;
    use bitbybit_ipc::builtin::{Empty, PingResponse};
    use bitbybit_ipc::client::BrokerClient;
    use bitbybit_ipc::protocol::PIPE_NAME;
    use bitbybit_platform_windows::pipe::{connect, server_is_local_system};
    use std::time::Duration;

    fn problem(e: &bitbybit_core::Error) -> LocalizedText {
        text!(
            "app.broker.unavailable",
            "The bitBybit service is not available: {0}",
            e.user_text.as_ref().map_or_else(|| e.message.clone(), |t| TextCatalog::default_catalog().resolve(t))
        )
    }

    #[derive(serde::Deserialize)]
    struct DeviceList {
        devices: Vec<DeviceSummary>,
    }

    pub fn load() -> Result<Loaded, LocalizedText> {
        let stream = connect(PIPE_NAME, Duration::from_secs(5)).map_err(|e| {
            text!("app.broker.unavailable", "The bitBybit service is not available: {0}", e.to_string())
        })?;
        // A pipe of the same name owned by anything but LocalSystem is an impostor; developers running the console
        // broker opt out explicitly.
        if !server_is_local_system(&stream) && std::env::var("BITBYBIT_DEV_BROKER").as_deref() != Ok("1") {
            return Err(text!(
                "app.broker.notGenuine",
                "The service pipe does not belong to the bitBybit service (it does not run as Local System). For safety bitBybit does not use it."
            ));
        }
        let client = BrokerClient::new(stream.clone(), stream);
        let ping: PingResponse =
            client.invoke("broker.ping", &Empty {}, None, Duration::from_secs(10)).map_err(|e| problem(&e))?;
        let network: NetworkOverview =
            client.invoke("network.overview", &Empty {}, None, Duration::from_secs(30)).map_err(|e| problem(&e))?;
        let list: DeviceList =
            client.invoke("devices.inventory", &Empty {}, None, Duration::from_secs(60)).map_err(|e| problem(&e))?;
        Ok(Loaded { broker_version: ping.broker_version, network, devices: list.devices })
    }
}

#[cfg(not(windows))]
mod broker {
    use super::*;

    pub fn load() -> Result<Loaded, LocalizedText> {
        Err(text!("app.broker.onlyWindows", "The bitBybit service exists only on Windows."))
    }
}

/// Audio lives in the user's session (default devices are per user): read and changed here, not by the service.
#[cfg(windows)]
mod audio {
    use super::*;
    use bitbybit_audio::changes::{AudioDevices, JournaledAudioChanges};
    use bitbybit_audio::profile::AudioRoles;
    use bitbybit_core::paths::AppPaths;
    use bitbybit_journal::JsonLinesJournal;
    use bitbybit_platform_windows::audio::CoreAudio;

    pub fn endpoints() -> Result<Vec<AudioEndpoint>, LocalizedText> {
        CoreAudio
            .endpoints()
            .map_err(|e| text!("app.audio.unavailable", "Windows audio is not available: {0}", e.message))
    }

    /// Outcome status of the revert (Reverted, DriftDetected, TargetGone, RevertFailed).
    pub fn revert(id: &str) -> Result<bitbybit_journal::ChangeStatus, LocalizedText> {
        use bitbybit_audio::changes::{DefaultEndpointRevert, EndpointEnabledRevert};
        let journal = JsonLinesJournal::new(AppPaths::from_environment().user_journal_file());
        let (a, b) = (DefaultEndpointRevert(&CoreAudio), EndpointEnabledRevert(&CoreAudio));
        let failed = |why: String| text!("app.audio.changeFailed", "The audio device could not be changed: {0}", why);
        let outcomes = bitbybit_recovery::RecoveryCoordinator::new(&journal, &[&a, &b])
            .revert(|r| r.id.to_string() == id, false)
            .map_err(|e| failed(e.message))?;
        outcomes
            .first()
            .map(|o| o.new_status)
            .ok_or_else(|| text!("app.changes.notActive", "This change is no longer active."))
    }

    pub fn make_default(id: &str) -> Result<(), LocalizedText> {
        let journal = JsonLinesJournal::new(AppPaths::from_environment().user_journal_file());
        let failed = |why: String| text!("app.audio.changeFailed", "The audio device could not be changed: {0}", why);
        match JournaledAudioChanges::new(&CoreAudio, &journal).set_default(
            id,
            AudioRoles::DEFAULT_DEVICE,
            time::OffsetDateTime::now_utc(),
        ) {
            Ok(true) => Ok(()),
            Ok(false) => Err(failed("Windows did not report the new default device".into())),
            Err(e) => Err(failed(e.message)),
        }
    }
}

#[cfg(not(windows))]
mod audio {
    use super::*;

    pub fn endpoints() -> Result<Vec<AudioEndpoint>, LocalizedText> {
        Err(text!("app.audio.unavailable", "Windows audio is not available: {0}", "Linux".to_owned()))
    }

    pub fn revert(_id: &str) -> Result<bitbybit_journal::ChangeStatus, LocalizedText> {
        Err(text!("app.changes.notActive", "This change is no longer active."))
    }

    pub fn make_default(_id: &str) -> Result<(), LocalizedText> {
        Err(text!("app.audio.changeFailed", "The audio device could not be changed: {0}", "Linux".to_owned()))
    }
}
